// seed: tests/seed.user1.spec.ts
// NOTE: шаги с page.route не проверялись в живом браузере (инструменты MCP без page.route) — написано строго по плану.
import { test, expect } from '@playwright/test';
import * as path from 'path';

test.use({
  storageState: path.resolve(__dirname, '../../../auth/user1.json'),
  viewport: { width: 390, height: 844 },
});

test.describe('Главная', () => {
  test('HM-04 Загрузка главной: единый skeleton без пустых секций #96a6e418 @prod-safe @mobile', async ({ page }) => {
    // 1. До перехода: задержка для `**/rest/v1/**` перед `route.continue()`.
    // Ответы держатся до конца съёмки (не меньше 6 с по плану) — скелетон не зависит от скорости загрузки бандла:
    // фиксированные 6 с от запроса могли истечь раньше последнего снимка (на WebKit бандл грузится дольше).
    let releaseHold!: () => void;
    const released = new Promise<void>((r) => (releaseHold = r));
    const cap = setTimeout(() => releaseHold(), 60_000); // страховка: не держать дольше 60 с
    const release = () => {
      clearTimeout(cap);
      releaseHold();
    };
    page.on('close', release);
    const handler = async (route: import('@playwright/test').Route) => {
      await Promise.all([new Promise((r) => setTimeout(r, 6000)), released]);
      await route.continue().catch(() => {});
    };
    await page.route('**/rest/v1/**', handler);

    // 2. Открыть `/home`.
    const nav = page.goto('/home');

    // 3. Снять текст страницы на 0.7, 1.5, 3, 5 с.
    // Сначала дождаться каркаса приложения (WebKit может ещё грузить бандл): любой текст / tablist / скелетон.
    // Ожидание каркаса — до 30 с (раньше 5 с: на iPhone/WebKit бандл не успевал), данные при этом всё ещё задержаны.
    await expect
      .poll(async () => (await page.locator('body').innerText()).trim().length > 0 || (await page.getByRole('tablist').count()) > 0, {
        timeout: 30_000,
      })
      .toBe(true);
    const marks = [700, 800, 1500, 2000]; // приращения до 0.7, 1.5, 3, 5 с (после появления каркаса)
    const snapshots: string[] = [];
    for (const ms of marks) {
      await page.waitForTimeout(ms);
      snapshots.push(await page.locator('body').innerText());
    }
    for (const text of snapshots) {
      // Во время загрузки: нет пустых секций и пустого состояния.
      expect(text).not.toContain('תפילות אחרונות');
      expect(text).not.toContain('התחל את המסע שלך');
      expect(text).toContain('טוענים את התפילה הקרובה…');
    }

    // 4. Снять задержку (`page.unroute`), дождаться данных.
    release();
    await page.unroute('**/rest/v1/**', handler);
    await nav.catch(() => {});
    await page.reload();
    await expect(page.getByRole('button', { name: 'התחל תפילה' })).toBeVisible({ timeout: 30_000 });
    await expect(page.getByText('תפילות אחרונות', { exact: true })).toBeVisible();
  });
});
